            raise ValueError("max_segment_bytes must be int >= 16")
        self._root = Path(root).resolve()
        self._root.mkdir(parents=True, exist_ok=True)
        self._max_segment_bytes = max_segment_bytes
        self._ index = Index()
        self._total_records = 0
        self._active = None
        self._closed = False
        self._recover()

    def _recover(self) -> None:
        paths = self._segment_paths()
        if not paths:
            self._active = Segment(self._root / "000001.seg", 1)
            return
        for path, seg_id in paths[:-1]:
            seg = Segment(path, seg_id)
            try:
                self._ingest(seg)
            finally:
                seg.close()
        path, seg_id = paths[-1]
        self._active = Segment(path, seg_id)
        self._ingest(self._active)

    def _segment_paths(self) -> list[tuple[Path, int]]:
        pat = re.compile(r"^(\d{6})\.seg$")
        res = []
        for p in self._root.iterdir():
            m = pat.match(p.name)
            if m:
                res.append((p, int(m.group(1))))
        res.sort(key=lambda x: x[1])
        return res

