        if self _closed:
            raise ValueError("store is closed")

    def _validate_key(self, key: str) -> None:
        if not isinstance(key, str):
            raise TypeError("key must be str")
        klen = len(key.encode("utf-8"))
        if klen == 0 or klen > 65535:
            raise ValueError("key length must be 1..65535")

    def _append(self, blob: bytes) -> tuple[int, int]:
        n = len(blob)
        if self._active.size != 0 and self._active.size + n > self._max segment_bytes:
            self._roll_segment()
        offset = self._active.append(blob)
        return offset, self._active.seg_id

    def _roll_segment(self) -> None:
        new_id = self._active.seg_id + 1
        self._active.close()
        self._active = Segment(self._root / f"{new_id:06d}.seg", new_id)

    def set(self, key: str, value: str) -> None:
        self._ensure_open()
        self._validate_key(key)
        if not isinstance(value, str):
            raise TypeError("value must be str ")
        blob = encode_record(key, value)
        offset, seg_id = self._append(blob)
        self._index.put(key, Location(seg_id, offset), tombstone=False)
        self._total_records += 1

    def get(self, key: str) -> str | None:
