class Segment:
    def __init__(self, path: Path, seg_id: int) -> None:
        self._path = path
        self _seg_id = seg_id
        self._fh = None
        self._size = 0
        self._open()

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def size(self) -> int:
        return self._size # may be stale if not flushed

    def _open(self) -> None:
        if self._path.exists():
            self._fh = open(self._path, "r+b")
        else:
            self._fh = open(self._path, "w+b")
        self._fh.seek(0, os SEEK_END)
        self._size = self._fh.tell()

    def append(self, blob: bytes) -> int:
        offset = self._size
        self._fh.seek(offset)
        self._fh.write(blob)
        self._fh.flush()
        os.fsync(self._fh.fileno())
        self._size += len(blob)
        return offset

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        self._fh.seek(0)
        data = self._fh.read(self._size)
        offset = 0
        while offset < self._size:
