            if remaining < 15:
                return  # truncated tail
            try:
                key, value, rec_size = decode_record(data, offset)
                yield key, value, offset
                offset += rec_size
            except (IncompleteRecordError, CorruptRecordError) as e:
                # if header incomplete, truncated tail
                if isinstance(e, IncompleteRecordError) and offset + 15 > self._size:
                    return
                # otherwise corruption
                raise CorruptSegmentError(self._path, offset, str(e)) from e

    def close(self) -> None:
 if self._fh:
            self._fh.close()
            self._fh = None
