        flags = 1
        vlen = 0
        vbytes = b""
    else:
        flags = 0 # value present
        vlen = len(value.encode("utf-8"))
        vbytes = value.encode("utf-8")
    klen = len(key.encode("utf-8"))
    crc = zlib.crc32(key.encode("utf-8") + vbytes) & 0xffffffff
    header = struct.pack(">I B H I I", 0x4b565231, flags, klen, vlen, crc)
    return header + key.encode("utf-8") + vbytes

def decode_record(buf: bytes, offset: int = 0) -> Tuple[str, str | None , int]:
    if offset + 15 > len(buf):
