"""Binary codec for KVR1 records."""

from __future__ import annotations

import struct
import zlib

from kvstore.errors import CorruptRecordError, IncompleteRecordError

MAGIC = b"KVR1"
HEADER_SIZE = 15
FLAG_VALUE = 0x00
FLAG_TOMBSTONE = 0x01
_HEADER = struct.Struct(">4sBHII")


def encode_record(key: str, value: str | None) -> bytes:
    """Encode a value record, or a tombstone when value is None."""
    if not isinstance(key, str):
        raise TypeError("key must be str")
    key_bytes = key.encode("utf-8")
    if not 1 <= len(key_bytes) <= 65535:
        raise ValueError("key UTF-8 length must be in 1..65535")
    flags, value_bytes = _value_bytes(value)
    crc = zlib.crc32(key_bytes + value_bytes) & 0xFFFFFFFF
    header = _HEADER.pack(MAGIC, flags, len(key_bytes), len(value_bytes), crc)
    return header + key_bytes + value_bytes


def decode_record(buf: bytes, offset: int = 0) -> tuple[str, str | None, int]:
    """Decode one record starting at offset.

    Length is checked before header validity so a short buffer is always
    incomplete, even when the partial bytes would not form a legal header.
    Structural problems are then reported before the CRC, and the CRC before
    UTF-8 decoding.
    """
    available = len(buf) - offset
    if available < HEADER_SIZE:
        raise IncompleteRecordError("incomplete record header")
    magic, flags, key_len, value_len, crc = _HEADER.unpack_from(buf, offset)
    total = HEADER_SIZE + key_len + value_len
    if available < total:
        raise IncompleteRecordError("incomplete record body")
    _check_structure(magic, flags, key_len, value_len)
    start = offset + HEADER_SIZE
    payload = buf[start:start + key_len + value_len]
    _check_crc(payload, crc)
    return _decode_text(payload, key_len, flags, total)


def _value_bytes(value: str | None) -> tuple[int, bytes]:
    if value is None:
        return FLAG_TOMBSTONE, b""
    if not isinstance(value, str):
        raise TypeError("value must be str or None")
    return FLAG_VALUE, value.encode("utf-8")


def _check_structure(magic: bytes, flags: int, key_len: int, value_len: int) -> None:
    if magic != MAGIC:
        raise CorruptRecordError("bad magic")
    if flags not in (FLAG_VALUE, FLAG_TOMBSTONE):
        raise CorruptRecordError("unknown flags")
    if key_len == 0:
        raise CorruptRecordError("key length is zero")
    if flags == FLAG_TOMBSTONE and value_len != 0:
        raise CorruptRecordError("tombstone with non-zero value_len")


def _check_crc(payload: bytes, expected: int) -> None:
    actual = zlib.crc32(payload) & 0xFFFFFFFF
    if actual != expected:
        raise CorruptRecordError("crc mismatch")


def _decode_text(payload: bytes, key_len: int, flags: int, total: int) -> tuple[str, str | None, int]:
    try:
        key = payload[:key_len].decode("utf-8")
        if flags == FLAG_TOMBSTONE:
            return key, None, total
        value = payload[key_len:].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptRecordError("invalid utf-8") from exc
    return key, value, total

"""One append-only segment file."""

from __future__ import annotations

import os
import pathlib
from collections.abc import Iterator
from typing import BinaryIO

from kvstore.errors import CorruptRecordError, CorruptSegmentError, IncompleteRecordError
from kvstore.record import decode_record

# A torn tail is left on disk so its bytes still count. The next append to this
# segment truncates back to the last complete record first; otherwise a later
# scan would stop at the tail and miss the new record.


class Segment:
    def __init__(self, path: pathlib.Path, seg_id: int) -> None:
        self._path = pathlib.Path(path)
        self._seg_id = seg_id
        self._fh = self._open()
        self._fh.seek(0, os.SEEK_END)
        self._size = self._fh.tell()
        self._logical: int | None = None

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def path(self) -> pathlib.Path:
        return self._path

    @property
    def size(self) -> int:
        """Current byte length of the file, including any torn tail."""
        return self._size

    def append(self, blob: bytes) -> int:
        """Append blob and return the offset it was written at."""
        self._discard_torn_tail()
        offset = self._size
        fh = self._require_open()
        fh.seek(offset)
        fh.write(blob)
        fh.flush()
        os.fsync(fh.fileno())
        self._size = offset + len(blob)
        self._logical = self._size
        return offset

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        """Yield complete records. A torn tail stops the scan; corruption raises."""
        data = self._read_all()
        offset = 0
        limit = len(data)
        while offset < limit:
            try:
                key, value, total = decode_record(data, offset)
            except IncompleteRecordError:
                self._logical = offset
                return
            except CorruptRecordError as exc:
                raise CorruptSegmentError(self._path, offset, str(exc)) from exc
            yield key, value, offset
            offset += total
        self._logical = offset

    def close(self) -> None:
        fh = self._fh
        self._fh = None
        if fh is not None and not fh.closed:
            fh.close()

    def _open(self) -> BinaryIO:
        if self._path.exists():
            return self._path.open("r+b")
        return self._path.open("w+b")

    def _require_open(self) -> BinaryIO:
        if self._fh is None or self._fh.closed:
            raise ValueError("segment is closed")
        return self._fh

    def _read_all(self) -> bytes:
        fh = self._require_open()
        fh.flush()
        fh.seek(0)
        data = fh.read()
        self._size = len(data)
        fh.seek(self._size)
        return data

    def _discard_torn_tail(self) -> None:
        logical = self._logical_end()
        if logical == self._size:
            return
        fh = self._require_open()
        fh.truncate(logical)
        fh.flush()
        self._size = logical
        self._logical = logical

    def _logical_end(self) -> int:
        if self._logical is not None:
            return self._logical
        data = self._read_all()
        self._logical = _logical_end(data)
        return self._logical


def _logical_end(data: bytes) -> int:
    offset = 0
    limit = len(data)
    while offset < limit:
        try:
            _, _, total = decode_record(data, offset)
        except IncompleteRecordError:
            return offset
        except CorruptRecordError:
            return offset
        offset += total
    return offset

"""In-memory key to record-location index."""

from __future__ import annotations

import dataclasses


@dataclasses.dataclass(frozen=True)
class Location:
    seg_id: int
    offset: int


class Index:
    def __init__(self) -> None:
        self._entries: dict[str, tuple[Location, bool]] = {}

    def put(self, key: str, loc: Location, *, tombstone: bool) -> None:
        """Record the newest location for key, replacing any earlier one."""
        self._entries[key] = (loc, tombstone)

    def get(self, key: str) -> Location | None:
        """Return the location of a live key, or None if absent or tombstoned."""
        found = self._entries.get(key)
        if found is None or found[1]:
            return None
        return found[0]

    def live_keys(self) -> list[str]:
        """Live keys ordered by newest-record position (seg_id, offset)."""
        ranked = [
            (loc.seg_id, loc.offset, key)
            for key, (loc, tombstone) in self._entries.items()
            if not tombstone
        ]
        ranked.sort()
        return [key for _, _, key in ranked]

    def tombstone_count(self) -> int:
        """Number of keys whose newest record is a tombstone."""
        return sum(1 for _, tombstone in self._entries.values() if tombstone)

    def __len__(self) -> int:
        """Number of live keys."""
        return sum(1 for _, tombstone in self._entries.values() if not tombstone)

"""Durable key-value store over append-only segment files."""

from __future__ import annotations

import os
import pathlib
import re
from typing import BinaryIO

from kvstore.index import Index, Location
from kvstore.record import encode_record
from kvstore.segment import Segment

# bool is an int subclass, but it is not a segment size.
_SEGMENT_NAME = re.compile(r"^(\d{6})\.seg$")


class Stats(tuple):  # placeholder so the real class can be defined below without confusion
    pass


import dataclasses  # noqa: E402  — kept near Stats; split only if needed


@dataclasses.dataclass(frozen=True)
class Stats:
    live_keys: int
    tombstones: int
    total_records: int
    dead_records: int
    segment_count: int
    bytes_on_disk: int


def list_segments(root: pathlib.Path) -> list[tuple[int, pathlib.Path]]:
    """Return (seg_id, path) for real segment files, in ascending id order."""
    found: list[tuple[int, pathlib.Path]] = []
    if not root.is_dir():
        return found
    for entry in root.iterdir():
        if not entry.is_file():
            continue
        match = _SEGMENT_NAME.match(entry.name)
        if match is None:
            continue
        found.append((int(match.group(1)), entry))
    found.sort(key=lambda item: item[0])
    return found


class KVStore:
    def __init__(self, root: str | os.PathLike, *, max_segment_bytes: int = 4096) -> None:
        self._max_segment_bytes = _require_max_segment_bytes(max_segment_bytes)
        self._root = pathlib.Path(root)
        self._index = Index()
        self._values: dict[str, str] = {}
        self._total_records = 0
        self._active: Segment | None = None
        self._closed = False
        self._root.mkdir(parents=True, exist_ok=True)
        try:
            self._open_segments()
        except Exception:
            self.close()
            raise

    def set(self, key: str, value: str) -> None:
        self._ensure_open()
        _require_key(key)
        _require_value(value)
        self._note(key, value, self._append(encode_record(key, value)))

    def get(self, key: str) -> str | None:
        self._ensure_open()
        _require_key(key)
        if self._index.get(key) is None:
            return None
        return self._values[key]

    def delete(self, key: str) -> bool:
        """Append a tombstone and return True only when key is currently live."""
        self._ensure_open()
        _require_key(key)
        if self._index.get(key) is None:
            return False
        self._note(key, None, self._append(encode_record(key, None)))
        return True

    def keys(self) -> list[str]:
        self._ensure_open()
        return self._index.live_keys()

    def stats(self) -> Stats:
        self._ensure_open()
        segments = list_segments(self._root)
        live = len(self._index)
        tombs = self._index.tombstone_count()
        total = self._total_records
        return Stats(
            live_keys=live,
            tombstones=tombs,
            total_records=total,
            dead_records=total - live - tombs,
            segment_count=len(segments),
            bytes_on_disk=self._bytes_on_disk(segments),
        )

    def close(self) -> None:
        active = self._active
        self._active = None
        self._closed = True
        if active is not None:
            active.close()

    def __enter__(self) -> KVStore:
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    def _open_segments(self) -> None:
        found = list_segments(self._root)
        if not found:
            self._active = Segment(self._segment_path(1), 1)
            self._ingest(self._active)
            return
        for seg_id, path in found[:-1]:
            self._ingest_closed(path, seg_id)
        seg_id, path = found[-1]
        self._active = Segment(path, seg_id)
        self._ingest(self._active)

    def _ingest_closed(self, path: pathlib.Path, seg_id: int) -> None:
        segment = Segment(path, seg_id)
        try:
            self._ingest(segment)
        finally:
            segment.close()

    def _ingest(self, segment: Segment) -> None:
        for key, value, offset in segment.scan():
            self._note(key, value, Location(segment.seg_id, offset))

    def _note(self, key: str, value: str | None, loc: Location) -> None:
        self._index.put(key, loc, tombstone=value is None)
        if value is None:
            self._values.pop(key, None)
        else:
            self._values[key] = value
        self._total_records += 1

    def _append(self, blob: bytes) -> Location:
        active = self._require_active()
        if active.size != 0 and active.size + len(blob) > self._max_segment_bytes:
            self._roll()
            active = self._require_active()
        offset = active.append(blob)
        return Location(active.seg_id, offset)

    def _roll(self) -> None:
        active = self._require_active()
        new_id = active.seg_id + 1
        active.close()
        self._active = Segment(self._segment_path(new_id), new_id)

    def _install_compacted(self, final: pathlib.Path, new_id: int, old_paths: list[pathlib.Path]) -> None:
        """Switch to a compacted segment after it has been moved into place."""
        self._ensure_open()
        if self._active is not None:
            self._active.close()
            self._active = None
        for path in old_paths:
            path.unlink()
        self._index = Index()
        self._values = {}
        self._total_records = 0
        self._active = Segment(final, new_id)
        self._closed = False
        self._ingest(self._active)

    def _bytes_on_disk(self, segments: list[tuple[int, pathlib.Path]]) -> int:
        total = 0
        active = self._active
        for seg_id, path in segments:
            if active is not None and seg_id == active.seg_id:
                total += active.size
            else:
                total += path.stat().st_size
        return total

    def _segment_path(self, seg_id: int) -> pathlib.Path:
        if not 0 <= seg_id <= 999999:
            raise ValueError(f"segment id {seg_id} does not fit in six digits")
        return self._root / f"{seg_id:06d}.seg"

    def _require_active(self) -> Segment:
        if self._active is None:
            raise ValueError("KVStore is closed")
        return self._active

    def _ensure_open(self) -> None:
        if self._closed or self._active is None:
            raise ValueError("KVStore is closed")


def _require_max_segment_bytes(value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 16:
        raise ValueError("max_segment_bytes must be an int >= 16")
    return value


def _require_key(key: object) -> None:
    if not isinstance(key, str):
        raise TypeError("key must be str")
    length = len(key.encode("utf-8"))
    if not 1 <= length <= 65535:
        raise ValueError("key UTF-8 length must be in 1..65535")


def _require_value(value: object) -> None:
    if not isinstance(value, str):
        raise TypeError("value must be str")

